if (req.method === 'POST' && req.url === '/entries') {
  let body = '';
  req.on('data', (c) => { body += c; });
  // 客户端中途断开（ECONNRESET 等）时流会发出 'error'，不处理会让进程崩溃
  req.on('error', () => {
    if (!res.writableEnded) res.destroy();
  });
  req.on('end', () => {
    let parsed;
    try {
      parsed = JSON.parse(body || '{}');
    } catch {
      // 非法 JSON 是客户端错误，返回 400，不能让进程崩溃
      res.statusCode = 400;
      res.end('bad request');
      return;
    }
    const { amount, note } = parsed;
    entries.push({ id: entries.length + 1, amount, note, ts: Date.now() });
    res.end('ok');
  });
  return;
}

